import{_ as t,o as i,c as a,a2 as o}from"./chunks/framework.Buc7gXeZ.js";const u=JSON.parse('{"title":"Testing","description":"","frontmatter":{},"headers":[],"relativePath":"permissions/testing.md","filePath":"permissions/testing.md"}'),n={name:"permissions/testing.md"};function s(r,e,l,c,d,h){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h1><p>36 Pest tests across four files, all green. This page maps each proven claim to where it&#39;s verified — use it to find the right file before adding a new scenario, and keep it honest: a row here with no matching test is a claim, not a fact.</p><h2 id="tests-feature-organization-organizationscopetest-php-13-tests" tabindex="-1"><code>tests/Feature/Organization/OrganizationScopeTest.php</code> (13 tests) <a class="header-anchor" href="#tests-feature-organization-organizationscopetest-php-13-tests" aria-label="Permalink to &quot;`tests/Feature/Organization/OrganizationScopeTest.php` (13 tests)&quot;">​</a></h2><p>The data-scope engine, <code>entity_scope</code> × <code>department_scope</code> as an intersection:</p><ul><li><code>entity_tree</code> sees the entity and every descendant.</li><li><code>entity</code> (single company) does not see the parent entity.</li><li><code>branch</code> on a non-main branch is confined to that branch, not the whole entity.</li><li><code>department_tree</code> sees a department and its sub-departments.</li><li>A child-entity manager does not gain scope over the parent, <strong>even sharing the same department catalog entry</strong> — the test that proves isolation comes from the entity dimension, not from a separate department row per company.</li><li><code>own</code> on both dimensions denies visibility into every other record.</li><li>A terminated employee loses visibility immediately, not at next login.</li><li>A user with no active employee record sees nothing (fail-closed).</li><li><code>super_admin</code> bypasses scope entirely, including with zero employee record of their own (the bootstrap-deadlock case).</li><li><code>status = suspended</code> denies scope exactly like <code>terminated</code>.</li><li>An <code>entity_tree</code> employee whose own entity was soft-deleted denies-all instead of crashing (guards <code>-&gt;entity</code> being <code>null</code> before calling <code>-&gt;descendantsAndSelf()</code>).</li><li>Reinstating a terminated employee restores visibility on the very next query.</li></ul><h2 id="cache-invalidation" tabindex="-1"><code>tests/Feature/Organization/OrganizationVersionCacheTest.php</code> (4 tests) <a class="header-anchor" href="#cache-invalidation" aria-label="Permalink to &quot;`tests/Feature/Organization/OrganizationVersionCacheTest.php` (4 tests) {#cache-invalidation}&quot;">​</a></h2><ul><li>A cached scope goes stale the instant the org tree changes — no logout/login, no manual cache clear.</li><li>One version bump invalidates every cached user scope simultaneously, not just the actor who triggered the write.</li><li>Reads with no intervening write keep serving the same cache key (<code>rememberForever</code> isn&#39;t silently thrashed by an accidental bump on every read).</li><li>A deny-all cached scope (no employee record) is invalidated by a tree change the same as any other — a user hired right after such a change isn&#39;t stuck deny-all.</li></ul><h2 id="tests-feature-organization-employeepermissionsynchronizertest-php-8-tests" tabindex="-1"><code>tests/Feature/Organization/EmployeePermissionSynchronizerTest.php</code> (8 tests) <a class="header-anchor" href="#tests-feature-organization-employeepermissionsynchronizertest-php-8-tests" aria-label="Permalink to &quot;`tests/Feature/Organization/EmployeePermissionSynchronizerTest.php` (8 tests)&quot;">​</a></h2><p>The functional-permissions engine and its grant tables:</p><ul><li>A job-title grant applies to every grade holding that title.</li><li>A grade-gated grant is withheld below its threshold grade, held once the employee reaches it.</li><li>A department grant reaches everyone in that department regardless of job title.</li><li>Someone outside the department does not gain its module access.</li><li>A named role attached to a job title is assigned to whoever holds it.</li><li>Terminating an employee immediately strips their permissions and roles.</li><li><code>hr:permissions:reconcile</code> detects and fixes drift from a grant added directly to a grant table, bypassing the synchronizer.</li></ul><h2 id="tests-feature-organization-functionalpermissionscopetest-php-4-tests" tabindex="-1"><code>tests/Feature/Organization/FunctionalPermissionScopeTest.php</code> (4 tests) <a class="header-anchor" href="#tests-feature-organization-functionalpermissionscopetest-php-4-tests" aria-label="Permalink to &quot;`tests/Feature/Organization/FunctionalPermissionScopeTest.php` (4 tests)&quot;">​</a></h2><p>Scenario 6 — functional permissions and data scope are independent axes:</p><ul><li>A user with maximal data scope (<code>entity_tree</code> + <code>department_tree</code>) is still denied a permission with no grant — organizational rank has no bearing on functional access.</li><li>A module with no grant is absent from the navigation tree entirely, not just blocked at the route.</li><li>Granting the department a permission flips <code>can()</code> without touching the employee row at all.</li><li>A permission-only grant (no role change) still invalidates the cached navigation tree — the regression test for the cache bug described in <a href="./functional-permissions#employeepermissionsynchronizer">functional-permissions.md</a>.</li></ul><h2 id="tests-feature-hr-organizationstructurescreenstest-php-7-tests" tabindex="-1"><code>tests/Feature/HR/OrganizationStructureScreensTest.php</code> (7 tests) <a class="header-anchor" href="#tests-feature-hr-organizationstructurescreenstest-php-7-tests" aria-label="Permalink to &quot;`tests/Feature/HR/OrganizationStructureScreensTest.php` (7 tests)&quot;">​</a></h2><p>Smoke coverage that the actual Livewire screens render, not just the underlying engine:</p><ul><li>Index and show pages return <code>200</code> for each of Entities, Branches, Departments, Job Grades, Job Titles, Employees — including the embedded &quot;Companies&quot; (Department) and &quot;Grades&quot; (JobTitle) sub-application tabs.</li><li>A user with no grant to a permission-gated Application is blocked (<code>404</code>) from both its index and show routes.</li></ul><h2 id="fixture-helpers-worth-knowing-about" tabindex="-1">Fixture helpers worth knowing about <a class="header-anchor" href="#fixture-helpers-worth-knowing-about" aria-label="Permalink to &quot;Fixture helpers worth knowing about&quot;">​</a></h2><p>Defined in <code>OrganizationScopeTest.php</code>, reused across the other three Organization test files via Pest&#39;s global function scoping:</p><ul><li><code>makeOrgTree()</code> — builds A (holding) → B → C, each with a main branch, a Finance→Payroll department chain attached to A.</li><li><code>makeEmployeeUser(array $attributes)</code> — an <code>Employee</code> with a real <code>User</code> attached.</li><li><code>plantEmployee(array $attributes)</code> — an <code>Employee</code> with no <code>User</code> (a &quot;colleague&quot; fixture). Both helpers auto-fill a consistent <code>job_title_id</code>/<code>job_grade_id</code> for the given <code>department_id</code> when the caller doesn&#39;t supply one, so fixtures satisfy <code>Employee::assertOrganizationallyConsistent()</code> (branch↔entity, job title↔department, job grade↔job title) without every test call site having to build that chain by hand.</li></ul>',19)])])}const g=t(n,[["render",s]]);export{u as __pageData,g as default};
